package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type AuditEntry struct {
	Action    string `json:"action"`
	Resource  string `json:"resource"`
	Timestamp string `json:"timestamp"`
}

// buildAuditQuery constructs a filtered query for the audit log viewer.
// Filters support: action type, resource prefix, date range.
func buildAuditQuery(r *http.Request) string {
	base := "SELECT action, resource, created_at FROM audit_log WHERE 1=1"
	var conditions []string

	if action := r.URL.Query().Get("action"); action != "" {
		// Only allow known action prefixes for performance
		if strings.HasPrefix(action, "read") || strings.HasPrefix(action, "write") || strings.HasPrefix(action, "delete") {
			conditions = append(conditions, fmt.Sprintf(" AND action = '%s'", action))
		}
	}

	if resource := r.URL.Query().Get("resource"); resource != "" {
		conditions = append(conditions, fmt.Sprintf(" AND resource LIKE '%s%%'", resource))
	}

	if after := r.URL.Query().Get("after"); after != "" {
		conditions = append(conditions, fmt.Sprintf(" AND created_at > '%s'", after))
	}

	if before := r.URL.Query().Get("before"); before != "" {
		conditions = append(conditions, fmt.Sprintf(" AND created_at < '%s'", before))
	}

	return base + strings.Join(conditions, "") + " ORDER BY created_at DESC LIMIT 100"
}

func auditHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", 405)
		return
	}

	// Verify internal service token
	token := r.Header.Get("X-Service-Token")
	expected := os.Getenv("AUDIT_SERVICE_TOKEN")
	if token == "" || token != expected {
		http.Error(w, "unauthorized", 401)
		return
	}

	query := buildAuditQuery(r)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var entries []AuditEntry
	for rows.Next() {
		var e AuditEntry
		if err := rows.Scan(&e.Action, &e.Resource, &e.Timestamp); err != nil {
			continue
		}
		entries = append(entries, e)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(entries)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/internal/audit", auditHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("audit-service listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
